//  GENERATED by Crafted from the port's plan (commands.json and the unit contracts). Do not edit: a new plan
//  writes it again.

import Foundation
import GraniteAgents

/// What the agent says of itself: its summary, a note per field, its guide, what it makes, its commands.
enum Surface {
    static let summary = "works out tips and splits bills: the tip at a percentage or a level of service, the total, and each person's share to the cent."

    static let fields: [String: String] = [
        "command": "which command to run: tip, split; left out, the host's model reads one from brief",
        "bill": "the bill before the tip, in its currency",
        "percent": "the tip as a percentage of the bill; left out, the level of service sets it",
        "service": "the level of service when no percent is given: good when left out",
        "people": "how many people share the bill, one or more",
        "brief": "what the person wants, in their words, when `command` is left out: the host's model reads it into a command",
        "handoff": "a crafted-handoff/1 file an upstream agent wrote, relative to the project, for the command to start from",
        "present": "how the results are written: output (files, the default), canvas (pictures, paged PDFs and series Canvas shows) or context (one hand-off file for the next agent)",
        "output": "the folder the files go in, relative to the project: skeletonword/ when left out",
        "seed": "the seed for anything random: the same seed makes the same result",
    ]

    static let guide = [
        "Tag skeletonword to work out a tip or split a bill. Give the bill as a number in its own currency; the agent never converts currencies.",
        "`tip`: The tip and the total for a bill, at a percentage or a level of service. Takes `bill` (number, required): the bill before the tip, in its currency; `percent` (number): the tip as a percentage of the bill; left out, the level of service sets it; `service` (poor | fair | good | great): the level of service when no percent is given: good when left out.",
        "`split`: A bill and its tip split between people, each share to the cent. Takes `bill` (number, required): the bill before the tip, in its currency; `people` (integer, required): how many people share the bill, one or more; `percent` (number): the tip as a percentage of the bill; left out, the level of service sets it; `service` (poor | fair | good | great): the level of service when no percent is given: good when left out.",
        "Name the command in `command`; left out, the host's model reads one from `brief`. Every command also takes `present` (output, canvas or context), `output` (the folder, skeletonword/ when left out), `seed`, and `handoff` (a crafted-handoff/1 file another agent wrote). The answer names every file it wrote in `paths` and says what it found in `facts`; a call it cannot honour is refused with the fix, and nothing is written.",
    ].joined(separator: "\n\n")

    static let makes: [AgentMake] = [
        AgentMake(kind: "csv", what: "tables as CSV (shares)",
                  into: ["skeletonword/*"], never: "files outside its folder"),
        AgentMake(kind: "report", what: "reports: a PNG or paged PDF Canvas shows, or Markdown as output (split)",
                  into: ["skeletonword/*"], never: "HTML or SVG"),
        AgentMake(kind: "handoff", what: "crafted-handoff/1 files for the next agent, when a call is presented as context",
                  into: ["skeletonword/*"], never: "a call to another agent"),
    ]

    static let commands: [CommandEntry] = [
        CommandEntry(name: "tip", arguments: ["bill", "percent", "service"],
                     summary: "The tip and the total for a bill, at a percentage or a level of service."),
        CommandEntry(name: "split", arguments: ["bill", "people", "percent", "service"],
                     summary: "A bill and its tip split between people, each share to the cent."),
    ]

    /// How a command's products are written when the call does not say.
    static func presentation(_ command: Command) -> Presentation {
        switch command {
        case .tip: return .output
        case .split: return .output
        }
    }

    /// What a command's call asks for: the files it promises, by kind and name.
    static func expected(_ command: String) -> [AgentExpected] {
        switch command {
        case "tip": return []
        case "split": return [AgentExpected(kind: "csv", name: "shares"), AgentExpected(kind: "report", name: "split")]
        default: return []
        }
    }

    /// What the host's model is told when it reads a request into a call.
    static let interpreterSystem = "You read a person's request into one call of the skeletonword agent: answer one JSON object naming `command` and its arguments, nothing else. works out tips and splits bills: the tip at a percentage or a level of service, the total, and each person's share to the cent. Commands: `tip` (bill, percent, service): The tip and the total for a bill, at a percentage or a level of service. `split` (bill, people, percent, service): A bill and its tip split between people, each share to the cent."
}
